css:
:root{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;--soft:#edf2f1}
body{background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei",system-ui,sans-serif;font-size:16px;line-height:1.95}
.paper-reading{max-width:1120px;margin:auto;padding:40px clamp(18px,5vw,58px) 80px;overflow-wrap:anywhere}
.paper-reading h1{font:normal clamp(32px,5vw,58px)/1.12 Georgia,"Noto Serif SC",serif;letter-spacing:-.025em;margin:18px 0 26px;text-wrap:balance}
.paper-reading h2{font-size:clamp(25px,3.5vw,34px);font-weight:500;line-height:1.4;margin:0 0 20px;text-wrap:balance}
.paper-reading h3{font-size:20px;font-weight:500;line-height:1.5}.paper-reading p{margin:12px 0 18px}
.paper-hero{padding:16px 0 38px;border-bottom:1px solid var(--line)}
.paper-hero .paper-thesis{font-size:18px;line-height:1.95;max-width:55ch}.paper-hero nav{display:flex;flex-wrap:wrap;gap:8px 22px;margin:26px 0 0}
.paper-hero nav a{font-size:13px;color:var(--accent);text-decoration:underline;text-underline-offset:6px}
.paper-chapter{padding:48px 0 34px;border-bottom:1px solid var(--line);min-width:0}
.paper-chapter :where(section,article,div,figure,fieldset){min-width:0}
.paper-chapter :where(table){display:block;max-width:100%;overflow:auto}
.paper-chapter :where(pre){white-space:pre-wrap;overflow-wrap:anywhere}
.paper-reading button{border:1px solid var(--line);background:transparent;color:var(--accent);padding:8px 14px;min-height:38px;border-radius:4px;font-size:13px;line-height:1.5}
.paper-reading button:hover{background:var(--soft)}.paper-reading button:disabled{opacity:.5;cursor:default}
.paper-reading input[type=range]{accent-color:var(--accent);max-width:100%;min-width:0}.paper-reading input[type=number]{width:90px}
.paper-reading select,.paper-reading input[type=number]{padding:7px 9px;border:1px solid var(--line);background:var(--paper);color:var(--ink);font-size:14px;border-radius:4px;max-width:100%}
.paper-reading input[type=checkbox]{accent-color:var(--warm)}.paper-reading label{font-size:14px;line-height:1.7}
.paper-reading svg,.paper-reading canvas{display:block;max-width:100%;height:auto}
.paper-reading details{padding:14px 0;border-top:1px solid var(--line);margin-top:20px}.paper-reading summary{cursor:pointer;color:var(--accent);font-size:14px}
.paper-reading table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}
.paper-reading th,.paper-reading td{padding:9px 7px;text-align:left;border-bottom:1px solid var(--line)}
.paper-reading button[data-source]{font-size:12px;color:var(--accent);border:0;padding:6px 0;margin-right:16px;text-decoration:underline;text-underline-offset:4px}
.paper-reading ::selection{background:#f3d5ac;color:#233342}.paper-reading :focus-visible{outline:2px solid var(--accent);outline-offset:4px}
.paper-reading .reading-limitations{font-size:14px;color:var(--muted);padding-top:28px}.paper-reading .reading-limitations h2{font-size:24px}
@media(max-width:480px){.paper-reading{padding-top:24px}.paper-chapter{padding-top:32px}.paper-hero .paper-thesis{font-size:16px}.paper-reading{font-size:15px}.paper-reading h2{font-size:25px}.paper-reading table{font-size:12px}}

@scope (#chapter-problem-statement){.chapter-container {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #e0e0e0;
  --paper: #f9f9f9;
  font-family: 'Segoe UI', system-ui, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  line-height: 1.6;
}

.chapter-header {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
  margin-bottom: 2rem;
}

.chapter-title {
  font-size: 2rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.chapter-lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.narrative-panel {
  background: #fff;
  padding: 1.5rem;
  border-left: 4px solid var(--accent);
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.section-heading {
  font-size: 1.4rem;
  margin-top: 0;
  color: var(--ink);
}

.narrative-panel p {
  font-size: 15px;
  margin-bottom: 1rem;
  text-align: justify;
}

.source-citation-block {
  margin-top: 1.5rem;
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.source-btn {
  background: var(--ink);
  color: #fff;
  border: none;
  padding: 0.4rem 0.8rem;
  font-size: 13px;
  cursor: pointer;
  border-radius: 3px;
  transition: opacity 0.2s;
}

.source-btn:hover {
  opacity: 0.8;
}

.visual-panel {
  background: #fff;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  max-width: 600px;
  margin-bottom: 1rem;
}

canvas {
  width: 100%;
  height: auto;
  background: #fff;
  border: 1px solid var(--line);
}

.canvas-controls {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: 100%;
  max-width: 600px;
  padding: 0.5rem;
  background: var(--paper);
  border-radius: 4px;
}

.canvas-controls label {
  font-size: 13px;
  color: var(--muted);
}

.canvas-controls input[type="range"] {
  width: 100%;
  cursor: pointer;
}

.legend-box {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: 13px;
  color: var(--muted);
  margin-top: 0.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.dot.dac { background: var(--warm); }
.dot.taylor { background: #ff6b6b; }
.dot.proposed { background: var(--accent); }

.line.crlb {
  width: 20px;
  height: 2px;
  background: var(--ink);
  display: inline-block;
}

.claims-section {
  background: #fff;
  padding: 1.5rem;
  border-top: 2px solid var(--line);
}

.claims-title {
  font-size: 1.2rem;
  margin-top: 0;
  color: var(--ink);
}

.claims-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.claim-item {
  padding: 1rem 0;
  border-bottom: 1px solid var(--line);
  font-size: 15px;
}

.claim-item:last-child {
  border-bottom: none;
}

.claim-conditions {
  font-size: 13px;
  color: var(--muted);
  margin: 0.3rem 0;
  font-style: italic;
}}
@scope (#chapter-math-model){:host {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #e0e0e0;
  --paper: #f9f9f9;
  --font-base: 16px;
  --font-control: 14px;
}

.chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  line-height: 1.6;
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  background: var(--paper);
}

.chapter-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 2rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.chapter-summary {
  font-size: 1.1rem;
  color: var(--muted);
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 2rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.text-block p {
  margin-bottom: 1rem;
  font-size: var(--font-base);
}

.interactive-lab {
  margin-top: 2rem;
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fff;
}

.lab-title {
  font-size: 1.25rem;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.lab-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 1.5rem;
  align-items: center;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.control-group label {
  font-size: var(--font-control);
  font-weight: 600;
}

input[type="range"] {
  width: 200px;
  accent-color: var(--accent);
}

.switch-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: var(--font-control);
  cursor: pointer;
}

.action-btn {
  padding: 0.5rem 1rem;
  background: var(--ink);
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: var(--font-control);
}

.action-btn:hover {
  background: #333;
}

.visualization-area {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

@media (max-width: 600px) {
  .visualization-area {
    grid-template-columns: 1fr;
  }
}

#math-model--geometry-canvas {
  width: 100%;
  height: auto;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fff;
}

.equation-panel {
  padding: 1rem;
  background: var(--paper);
  border-radius: 4px;
  border: 1px solid var(--line);
}

.equation-panel h3 {
  margin: 0 0 0.5rem 0;
  font-size: 1rem;
}

.equation-display {
  font-family: 'Courier New', monospace;
  background: #fff;
  padding: 0.5rem;
  border-radius: 4px;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
  overflow-x: auto;
}

.highlight-term {
  color: var(--warm);
  font-weight: 700;
  cursor: pointer;
  padding: 0 0.25rem;
  border-radius: 2px;
}

.highlight-term.active {
  background: var(--warm);
  color: #000;
}

.equation-note {
  font-size: 0.85rem;
  color: var(--muted);
  margin: 0.5rem 0;
}

.status-box {
  padding: 0.5rem;
  background: #fff;
  border-left: 3px solid var(--accent);
  font-size: 0.9rem;
}

.evidence-column {
  border-left: 1px solid var(--line);
  padding-left: 1.5rem;
}

.evidence-column h3 {
  font-size: 1rem;
  margin: 0 0 1rem 0;
}

.evidence-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.evidence-item {
  margin-bottom: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.source-btn {
  align-self: flex-start;
  padding: 0.25rem 0.5rem;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 0.8rem;
  cursor: pointer;
}

.source-btn:hover {
  border-color: var(--accent);
}

.evidence-text {
  font-size: 0.9rem;
  color: var(--muted);
}}
@scope (#chapter-linearization-strategy){:host {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #ecf0f1;
  --paper: #ffffff;
  --bg: #f4f7f6;
  --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: "SF Mono", Monaco, Consolas, "Liberation Mono", monospace;
  display: block;
  font-family: var(--font-main);
  color: var(--ink);
  background: var(--bg);
  padding: 2rem;
  box-sizing: border-box;
}

.chapter-container {
  max-width: 1200px;
  margin: 0 auto;
  background: var(--paper);
  border: 1px solid var(--line);
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
  border-radius: 4px;
  overflow: hidden;
}

.chapter-header {
  border-bottom: 2px solid var(--ink);
  padding: 1.5rem 2rem;
  background: var(--ink);
  color: var(--paper);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.chapter-title {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.chapter-meta {
  font-size: 0.85rem;
  opacity: 0.8;
  font-family: var(--font-mono);
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 2rem;
  padding: 2rem;
}

@media (max-width: 900px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

/* Main Visual Area */
.main-visual {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.equation-card {
  background: #fafafa;
  border: 1px solid var(--line);
  border-left: 4px solid var(--muted);
  padding: 1.5rem;
  border-radius: 2px;
  transition: all 0.3s ease;
}

.equation-card.active {
  border-left-color: var(--accent);
  background: #f0ffff;
  box-shadow: 0 2px 8px rgba(0, 206, 209, 0.15);
}

.equation-card h3 {
  margin-top: 0;
  font-size: 1.1rem;
  color: var(--ink);
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
  margin-bottom: 1rem;
}

.text-block {
  font-size: 0.95rem;
  line-height: 1.6;
  color: #444;
  margin-bottom: 1rem;
}

.math-display {
  font-family: var(--font-mono);
  background: #fff;
  padding: 1rem;
  border: 1px solid #eee;
  text-align: center;
  font-size: 1.1rem;
  color: var(--ink);
  margin-bottom: 1rem;
  overflow-x: auto;
}

.matrix-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 1rem;
}

.matrix-bracket {
  border-left: 2px solid var(--ink);
  border-right: 2px solid var(--ink);
  padding: 0.5rem 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  background: #fff;
}

.matrix-row {
  font-family: var(--font-mono);
  font-size: 1rem;
}

.matrix-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

/* Control Panel */
.control-panel {
  background: #2c3e50;
  color: #fff;
  padding: 1.5rem;
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.control-panel h3 {
  margin: 0 0 1rem 0;
  font-size: 1.1rem;
  color: var(--accent);
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 0.5rem;
}

.stepper-controls {
  display: flex;
  gap: 1rem;
}

.step-item {
  flex: 1;
  background: rgba(255,255,255,0.05);
  padding: 0.8rem;
  border-radius: 4px;
  border: 1px solid transparent;
  cursor: default;
  transition: all 0.3s;
}

.step-item.active {
  background: rgba(0, 206, 209, 0.1);
  border-color: var(--accent);
}

.step-item.completed {
  background: rgba(0, 206, 209, 0.2);
  border-color: var(--accent);
}

.step-indicator {
  font-weight: bold;
  font-size: 0.9rem;
  margin-bottom: 0.3rem;
  color: var(--accent);
}

.step-desc {
  font-size: 0.8rem;
  color: #ccc;
}

.calculation-display {
  background: rgba(0,0,0,0.2);
  padding: 1rem;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 0.9rem;
}

.calc-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 0.3rem;
}

.calc-row:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.calc-row .label {
  color: #aaa;
}

.calc-row .value {
  color: var(--accent);
  font-weight: bold;
}

.action-buttons {
  display: flex;
  gap: 1rem;
}

button {
  font-family: var(--font-main);
  cursor: pointer;
  border: none;
  outline: none;
  transition: background 0.2s;
}

.btn-primary {
  flex: 2;
  background: var(--accent);
  color: #004d40;
  font-weight: bold;
  padding: 0.8rem;
  border-radius: 2px;
  font-size: 1rem;
}

.btn-primary:hover {
  background: #00bfbf;
}

.btn-primary:disabled {
  background: #555;
  color: #888;
  cursor: not-allowed;
}

.btn-secondary {
  flex: 1;
  background: transparent;
  border: 1px solid #555;
  color: #ccc;
  padding: 0.8rem;
  border-radius: 2px;
}

.btn-secondary:hover {
  border-color: #888;
  color: #fff;
}

.source-btn {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--line);
  padding: 0.4rem 0.8rem;
  font-size: 0.8rem;
  border-radius: 2px;
  margin-top: 0.5rem;
  align-self: flex-start;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.source-btn.small {
  font-size: 0.75rem;
  padding: 0.2rem 0.5rem;
  margin-top: 0;
  align-self: flex-start;
}

/* Evidence Section */
.evidence-section {
  padding: 2rem;
  background: #fafafa;
  border-top: 1px solid var(--line);
}

.evidence-section h3 {
  margin-top: 0;
  font-size: 1.2rem;
  color: var(--ink);
  margin-bottom: 0.5rem;
}

.section-intro {
  font-size: 0.95rem;
  color: #555;
  margin-bottom: 1.5rem;
  max-width: 800px;
}

.table-wrapper {
  overflow-x: auto;
  margin-bottom: 1rem;
  border: 1px solid var(--line);
  background: #fff;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
  min-width: 600px;
}

.data-table th, .data-table td {
  padding: 0.8rem 1rem;
  text-align: right;
  border-bottom: 1px solid var(--line);
}

.data-table th {
  background: #f0f0f0;
  color: var(--ink);
  font-weight: 600;
  text-align: center;
}

.data-table td:first-child, .data-table th:first-child {
  text-align: left;
  font-weight: 600;
  color: var(--ink);
  background: #fafafa;
}

.data-table tr:hover td {
  background: #f9f9f9;
}

.table-notes {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.5;
}

.table-notes strong {
  color: var(--ink);
}}
@scope (#chapter-step1-estimator){:host(.chapter-scope) {
  display: block;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #1a1a1a);
  background: var(--paper, #f9f9f9);
  padding: 2rem;
  line-height: 1.6;
}

.section-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--line, #e0e0e0);
  padding-bottom: 1rem;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--ink, #1a1a1a);
  margin: 0 0 0.5rem 0;
}

.section-takeaway {
  font-size: 1rem;
  color: var(--muted, #666);
  max-width: 800px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.main-visual {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.diagram-container {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  overflow: hidden;
  height: 300px;
}

#step1-estimator--geo-diagram {
  width: 100%;
  height: 100%;
}

.formula-block {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-left: 4px solid var(--accent, #00CED1);
  padding: 1rem;
  border-radius: 4px;
}

.formula-label {
  font-size: 0.875rem;
  color: var(--muted, #666);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.math-display {
  font-family: 'Times New Roman', serif;
  font-size: 1.25rem;
  text-align: center;
  padding: 0.5rem 0;
  color: var(--ink, #1a1a1a);
}

.formula-note {
  font-size: 0.875rem;
  color: var(--muted, #666);
  margin-top: 0.5rem;
  text-align: center;
}

.interactive-panel {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.control-group {
