  if (!slider || !noiseValueDisplay || !resetBtn) return;

  const width = canvas.width;
  const height = canvas.height;
  const padding = { top: 40, right: 30, bottom: 50, left: 60 };
  const plotWidth = width - padding.left - padding.right;
  const plotHeight = height - padding.top - padding.bottom;

  const xMin = -5; 
  const xMax = -3; 
  const yMin = 0; 
  const yMax = 1000; 

  const dacThresholdLog = Math.log10(0.000016);
  const proposedThresholdLog = Math.log10(0.0001);

  function logToX(logVal) {
    return padding.left + ((logVal - xMin) / (xMax - xMin)) * plotWidth;
  }

  function mseToY(mse) {
