  function drawGrid() {
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;
    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#666';
    ctx.textAlign = 'center';

    for (let i = 0; i <= 5; i++) {
      const xVal = xMin + (i * (xMax - xMin) / 5);
      const x = logToX(xVal);
      ctx.beginPath();
      ctx.moveTo(x, padding.top);
      ctx.lineTo(x, height - padding.bottom);
      ctx.stroke();
      ctx.fillText(xVal.toFixed(1), x, height - padding.bottom + 20);
    }

    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const yVal = yMin + (i * (yMax - yMin) / 5);
      const y = mseToY(yVal);
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();
      ctx.fillText(yVal.toFixed(0), padding.left - 10, y + 4);
    }

