    ctx.textAlign = 'center';
    ctx.fillText('log₁₀(σ²)', width / 2, height - 10);
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('MSE', 0, 0);
    ctx.restore();
  }

  function drawCRLB() {
    ctx.strokeStyle = '#1a1a1a';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    const yCRLB = mseToY(10);
    ctx.moveTo(padding.left, yCRLB);
    ctx.lineTo(width - padding.right, yCRLB);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#1a1a1a';
    ctx.textAlign = 'left';
    ctx.fillText('CRLB', padding.left + 5, yCRLB - 5);
  }

  function drawDAC(logSigmaSq) {
    ctx.strokeStyle = '#FFBF00';
    ctx.lineWidth = 3;
    ctx.beginPath();
    let started = false;
    for (let x = xMin; x <= xMax; x += 0.05) {
      let mse;
      if (x < dacThresholdLog) {
        mse = 10 * Math.pow(10, (x - xMin) * 0.5);
      } else {
        mse = 10 + Math.pow(10, (x - dacThresholdLog) * 3) * 50;
      }
      const plotX = logToX(x);
      const plotY = mseToY(mse);
      if (!started) {
        ctx.moveTo(plotX, plotY);
        started = true;
      } else {
        ctx.lineTo(plotX, plotY);
      }
    }
    ctx.stroke();
  }

  function drawTaylor(logSigmaSq) {
    ctx.strokeStyle = '#ff6b6b';
