  const canvas = document.getElementById('math-model--geometry-canvas');
  const ctx = canvas.getContext('2d');
  const sensorCountInput = document.getElementById('math-model--sensor-count');
  const mDisplay = document.getElementById('math-model--m-display');
  const linearArrayToggle = document.getElementById('math-model--linear-array-toggle');
  const resetBtn = document.getElementById('math-model--reset-btn');
  const statusText = document.getElementById('math-model--status-text');
  const quadraticTerm = document.getElementById('math-model--quadratic-term');

  let M = 3;
  let isLinearArray = false;
  let highlightQuadratic = false;
  let sensors = [];
  let source = { x: 300, y: 150 };

  function initSensors() {
    sensors = [];
    if (isLinearArray) {
      const spacing = 50;
      const startX = 100;
      for (let i = 0; i < M; i++) {
        sensors.push({
          x: startX + i * spacing,
          y: 200,
          id: i
        });
      }
    } else {
      const centerX = 300;
      const centerY = 200;
      const radius = 120;
      for (let i = 0; i < M; i++) {
        const angle = (2 * Math.PI * i) / M;
