          x: centerX + radius * Math.cos(angle),
          y: centerY + radius * Math.sin(angle),
          id: i
        });
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw grid
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth = 1;
    for (let x = 0; x < canvas.width; x += 50) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y < canvas.height; y += 50) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(canvas.width, y);
      ctx.stroke();
    }

    // Draw sensors
    sensors.forEach((sensor, idx) => {
      ctx.fillStyle = highlightQuadratic ? '#FFBF00' : '#00CED1';
      ctx.beginPath();
      ctx.arc(sensor.x, sensor.y, 8, 0, 2 * Math.PI);
      ctx.fill();
      ctx.fillStyle = '#000';
      ctx.font = '12px sans-serif';
      ctx.fillText(`S${idx + 1}`, sensor.x + 12, sensor.y + 4);

      // Draw hyperbola branches (simplified)
      if (idx > 0) {
        ctx.strokeStyle = highlightQuadratic ? 'rgba(255, 191, 0, 0.3)' : 'rgba(0, 206, 209, 0.3)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        const dx = source.x - sensor.x;
        const dy = source.y - sensor.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const refDist = Math.sqrt((source.x - sensors[0].x) ** 2 + (source.y - sensors[0].y) ** 2);
        const diff = dist - refDist;

        // Simplified hyperbola drawing
        const a = Math.abs(diff) / 2;
        const c = dist / 2;
        const b = Math.sqrt(c * c - a * a);

        ctx.ellipse(
          (source.x + sensor.x) / 2,
          (source.y + sensor.y) / 2,
          a + 20,
          b + 10,
          Math.atan2(dy, dx),
          0,
          2 * Math.PI
        );
        ctx.stroke();
      }
    });

    // Draw source
    ctx.fillStyle = '#FF4500';
    ctx.beginPath();
    ctx.arc(source.x, source.y, 10, 0, 2 * Math.PI);
    ctx.fill();
    ctx.fillStyle = '#000';
    ctx.fillText('Source', source.x + 15, source.y);
  }

  function updateStatus() {
    let status = '';
    if (M === 3) {
      status = '恰定 (3 方程，3 未知数)';
    } else if (M >= 4) {
      status = `超定 (${M} 方程，3 未知数) - 需最小二乘法`;
    }
    statusText.textContent = status;
  }

  function handleInput() {
    M = parseInt(sensorCountInput.value);
    mDisplay.textContent = M;
    isLinearArray = linearArrayToggle.checked;
    initSensors();
    updateStatus();
    draw();
  }

  sensorCountInput.addEventListener('input', handleInput);
  linearArrayToggle.addEventListener('change', handleInput);
  resetBtn.addEventListener('click', () => {
    sensorCountInput.value = 3;
    linearArrayToggle.checked = false;
    highlightQuadratic = false;
